{
  "lines": [
    {
      "id": "chapter.balance",
      "tiers": [
        {
          "id": "chapter.balance:t1",
          "title": "Щупальца порядка",
          "phrase": "Ты прошёл 50% главы баланса: регулярность, практика и наблюдения или план складываются в систему. Осьминог-организатор уже перестал путать гантель с блокнотом.",
          "imagePrompt": "A round-headed octopus steadies a small seesaw with a dumbbell on one end and an open notebook on the other. A rolled exercise mat rests beside it; two curled arms cautiously adjust the plank.",
          "fishMarkup": "[warm]Ты прошёл 50% главы баланса: регулярность, практика и наблюдения или план складываются в систему. [playful]Осьминог-организатор уже перестал путать гантель с блокнотом.",
          "audioText": "Ты прошёл 50% главы баланса: регулярность, практика и наблюдения или план складываются в систему. Осьминог-организатор уже перестал путать гантель с блокнотом."
        },
        {
          "id": "chapter.balance:t2",
          "title": "Восемь рук в деле",
          "phrase": "В твоей истории — 75% главы баланса с её регулярностью, практикой и наблюдениями или планом. Осьминог навёл порядок даже среди собственных щупалец.",
          "imagePrompt": "A round-headed octopus operates a revolving three-tray stand carrying a dumbbell, a rolled exercise mat, and an open notebook. Its arms weave neatly between the trays, with one spare arm catching a slipping pencil.",
          "fishMarkup": "[confident]В твоей истории — <emphasis>75% главы баланса</emphasis> с её регулярностью, практикой и наблюдениями или планом. [playful]Осьминог навёл порядок даже среди собственных щупалец.",
          "audioText": "В твоей истории — 75% главы баланса с её регулярностью, практикой и наблюдениями или планом. Осьминог навёл порядок даже среди собственных щупалец."
        },
        {
          "id": "chapter.balance:t3",
          "title": "Всё схвачено, чай заварен",
          "phrase": "Ты завершил главу баланса на 100%: базовые ступени регулярности, практики и наблюдений или плана пройдены. Осьминог всё схватил — и оставил щупальце для чая.",
          "imagePrompt": "A round-headed octopus reclines in a rocking chair woven from four of its own arms. Three other arms neatly hold a dumbbell, a rolled exercise mat, and an open notebook; the last arm raises a tiny teacup with absolute composure.",
          "fishMarkup": "[triumphant]Ты завершил главу баланса на 100%: базовые ступени регулярности, практики и наблюдений или плана пройдены. [playful]Осьминог всё схватил — <slow>и оставил щупальце для чая.</slow>",
          "audioText": "Ты завершил главу баланса на 100%: базовые ступени регулярности, практики и наблюдений или плана пройдены. Осьминог всё схватил — и оставил щупальце для чая."
        }
      ]
    },
    {
      "id": "chapter.worlds",
      "tiers": [
        {
          "id": "chapter.worlds:t1",
          "title": "Ракушка с пересадкой",
          "phrase": "Ты прошёл 50% главы о 10 мирах, 30 сюжетных днях и 12 активных неделях. Улитка-проводник уложила приключения в чемодан — носок тоже влез.",
          "imagePrompt": "A tiny explorer snail peers into its half-open suitcase-shaped shell, where a winding path crosses miniature island worlds. One feeler props up the lid as the snail tests a little bridge; a rolled sock sits in a side pocket.",
          "fishMarkup": "[warm]Ты прошёл 50% главы о 10 мирах, 30 сюжетных днях и 12 активных неделях. [playful]Улитка-проводник уложила приключения в чемодан — носок тоже влез.",
          "audioText": "Ты прошёл 50% главы о 10 мирах, 30 сюжетных днях и 12 активных неделях. Улитка-проводник уложила приключения в чемодан — носок тоже влез."
        },
        {
          "id": "chapter.worlds:t2",
          "title": "Миры ручной клади",
          "phrase": "За твоими плечами 75% главы о 10 мирах, 30 сюжетных днях и 12 активных неделях. В чемодане улитки у носка уже появились соседи.",
          "imagePrompt": "A tiny explorer snail unfolds its suitcase-shaped shell into a branching network of miniature worlds connected by arched bridges. It stretches between two islands to rearrange them; a rolled sock is squeezed into a narrow gap.",
          "fishMarkup": "[confident]За твоими плечами <emphasis>75% главы</emphasis> о 10 мирах, 30 сюжетных днях и 12 активных неделях. [playful]В чемодане улитки у носка уже появились соседи.",
          "audioText": "За твоими плечами 75% главы о 10 мирах, 30 сюжетных днях и 12 активных неделях. В чемодане улитки у носка уже появились соседи."
        },
        {
          "id": "chapter.worlds:t3",
          "title": "Вселенная помещается, носок нет",
          "phrase": "Ты завершил главу на 100%: 10 миров, 30 сюжетных дней и 12 активных недель в твоей истории. Вселенная в чемодан влезла, а носок — нет!",
          "imagePrompt": "A tiny explorer snail tries to close its suitcase-shaped shell around a swirling cluster of miniature worlds linked by winding paths. One oversized sock sticks out and blocks the lid; the snail presses down with a baffled expression.",
          "fishMarkup": "[triumphant]Ты завершил главу на 100%: 10 миров, 30 сюжетных дней и 12 активных недель в твоей истории. [playful]Вселенная в чемодан влезла, <slow>а носок — нет!</slow>",
          "audioText": "Ты завершил главу на 100%: 10 миров, 30 сюжетных дней и 12 активных недель в твоей истории. Вселенная в чемодан влезла, а носок — нет!"
        }
      ]
    }
  ]
}
